    parent: Dict[str, str] = {}

    def find(node: str) -> str:
        root = node
        while parent.get(root, root) != root:
            root = parent[root]
        # path compression
        while node != root:
            nxt = parent[node]
            parent[node] = root
            node = nxt
        return root

    def union(a: str, b: str) -> bool:
        ra, rb = find(a), find(b)
        if ra == rb:
            return False
        parent[ra] = rb
        return True

    kept: List[Tuple[str, str, int]] = []
    for a, b, km in edges:
        if a == b:
            continue
        if a > b:
            a, b = b, a
        if union(a, b):
            kept.append((a, b, km))

    kept.sort(key=lambda e: (e[2], e[0], e[1]))
