        if v not in adj:
            adj[v] = {}

        if u != v:
            if v not in adj[u] or w < adj[u][v]:
                adj[u][v] = w
            if not directed:
                if u not in adj[v] or w < adj[v][u]:
                    adj[v][u] = w

    return adj"
